import javax.crypto.KeyGenerator;
import javax.crypto.NoSuchPaddingException;
import javax.crypto.SecretKey;","reason":"Import KeyGenerator so first use creates the current wrapping key through AndroidKeyStore rather than deriving or reusing the legacy key.","symbol":"crypto imports"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/Encryptor.java","original_code":"    private static final String MASTER = "masterKey";
    private KeyStore mKeyStore;","edit_kind":"constant","corrected_code":"    private static final String MASTER = "masterKey";
    private static final String CURRENT_MASTER = "currentMasterKey";
    private KeyStore mKeyStore;","reason":"Add a persistent identity distinct from the established legacy master-key alias so current records can identify and reload their generated wrapping key without changing legacy resolution.","symbol":"Encryptor wrapping-key aliases"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/Encryptor.java","original_code":"    public Encryptor(Context ctx) throws KeyStoreException, CertificateException,
            NoSuchAlgorithmException, IOException {
        mKeyStore = KeyStore.getInstance("AndroidKeyStore");
        mKeyStore.load(null);
    }","edit_kind":"method","corrected_code":"    public Encryptor(Context ctx) throws KeyStoreException, CertificateException,
            NoSuchAlgorithmException, IOException {
        mKeyStore = KeyStore.getInstance("AndroidKeyStore");
        mKeyStore.load(null);
    }

    private SecretKey getLegacyWrappingKey() {
        try {
            Key key = mKeyStore.getKey(MASTER, null);
            return key instanceof SecretKey ? (SecretKey) key : null;
        } catch (Exception e) {
            Log.e(LOGTAG, "Exception", e);
            return null;
        }
    }

    private SecretKey getCurrentWrappingKey() throws InvalidKeyException {
        try {
            Key key = mKeyStore.getKey(CURRENT_MASTER, null);
            if (key != null) {
                if (key instanceof SecretKey) {
                    return (SecretKey) key;
                }
                throw new InvalidKeyException("Current wrapping-key alias is not a secret key");
            }

            KeyGenerator keyGenerator = KeyGenerator.getInstance(
                    KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore");
            keyGenerator.init(new KeyGenParameterSpec.Builder(CURRENT_MASTER,
                    KeyProperties.PURPOSE_ENCRYPT | KeyProperties.PURPOSE_DECRYPT)
                    .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                    .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                    .build());
            return keyGenerator.generateKey();
        } catch (GeneralSecurityException e) {
            throw new InvalidKeyException("Unable to resolve current wrapping key", e);
        }
    }","reason":"Retain the established legacy alias lookup and add a persistent AndroidKeyStore-backed current-key lifecycle. The key is generated only when its current alias is absent and subsequently reloaded from that alias; no caller-selected GCM nonce or parameters are provided to the AndroidKeyStore key.","symbol":"Encryptor constructor and wrapping-key resolution"},{"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/Encryptor.java","original_code":"    public Map<String, EncryptedKey> encryptToken(SecretKey key) throws
            NoSuchAlgorithmException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, NoSuchPaddingException, IOException {
        Map<String, EncryptedKey> data = new HashMap<>();

        Key mk = null;
        try {
            mk = mKeyStore.getKey(MASTER, null);
        } catch (Exception e) {
            Log.e(LOGTAG, "Exception", e);
        }

        // Encrypt token key
        EncryptedKey ekc = EncryptedKey.encrypt((SecretKey) mk, key);

        data.put("key", ekc);
        return data;
    }","edit_kind":"method","corrected_code":"    public Map<String, EncryptedKey> encryptToken(SecretKey key) throws
            NoSuchAlgorithmException, IllegalBlockSizeException, InvalidKeyException,
            BadPaddingException, NoSuchPaddingException, IOException {
        Map<String, EncryptedKey> data = new HashMap<>();

        SecretKey currentWrappingKey = getCurrentWrappingKey();

        // Encrypt token key
        EncryptedKey ekc = EncryptedKey.encrypt(currentWrappingKey, key, CURRENT_MASTER);

        data.put("key", ekc);
        return data;
    }","reason":"Route every newly encrypted token through the generated current wrapping key and identify that key in the versioned EncryptedKey record, while preserving the public method name and checked-exception contract.","symbol":"Encryptor.encryptToken"}],"manual_review_required":true,"provided_contracts":["Encryptor.encryptToken preserves its public signature and writes current records using EncryptedKey.encrypt(SecretKey, SecretKey, String) with wrapping-key identity "currentMasterKey".","The current Encryptor wrapping key is generated through AndroidKeyStore KeyGenerator on first use and reloaded from the same alias thereafter.","The established "masterKey" AndroidKeyStore lookup remains available through getLegacyWrappingKey for legacy-record resolution."],"required_contracts":["EncryptedKey.encrypt(SecretKey, SecretKey, String) must accept "currentMasterKey", serialize it in a version-1 current record, and retain AndroidKeyStore-provider-generated cipher parameters for decryption.","MasterKey must use the identical "currentMasterKey" generated-key lifecycle for current writes and retain its PBKDF2-derived key only as the legacy decrypt argument.","The dedicated EncryptedKey instrumentation tests must cover Encryptor current-key first-use/reuse and current-record round trips without supplying GCM parameters to an AndroidKeyStore encryption initialization."],"source_file_path":"mobile/src/main/java/org/fedorahosted/freeotp/encryptor/Encryptor.java","required_tests":["In the dedicated EncryptedKey instrumentation test, invoke Encryptor.encryptToken twice and verify both current records identify "currentMasterKey" and decrypt through the same reloaded AndroidKeyStore key.","Verify first-use current-key creation and later current-key lookup use the same AndroidKeyStore alias.","Verify legacy-format records remain decryptable through the retained legacy-key path in the coordinated EncryptedKey and MasterKey changes."]}
